import{_ as r,I as o,c as i,o as s,j as t,J as c,ag as d,a}from"./chunks/framework.ARG558ZT.js";const g=JSON.parse('{"title":"Resumable execution and uncertain effects","description":"","frontmatter":{},"headers":[],"relativePath":"applied-ai/workflows/resumable-runs.md","filePath":"applied-ai/workflows/resumable-runs.md"}'),l={name:"applied-ai/workflows/resumable-runs.md"};function p(u,e,h,m,b,f){const n=o("MermaidDiagram");return s(),i("div",null,[e[0]||(e[0]=t("h1",{id:"resumable-execution-and-uncertain-effects",tabindex:"-1"},[a("Resumable execution and uncertain effects "),t("a",{class:"header-anchor",href:"#resumable-execution-and-uncertain-effects","aria-label":"Permalink to “Resumable execution and uncertain effects”"},"​")],-1)),e[1]||(e[1]=t("p",null,[a("Persisting a stage name is not enough to resume useful work. The next step also needs its immutable input, checked result, current authority, configuration, remaining budget and any stable operation identity. The existing "),t("code",null,"JobStore"),a(", approval executor and spend ledger each solve one part; their independent transactions do not automatically compose.")],-1)),e[2]||(e[2]=t("h2",{id:"a-checkpoint-is-an-application-contract",tabindex:"-1"},[a("A checkpoint is an application contract "),t("a",{class:"header-anchor",href:"#a-checkpoint-is-an-application-contract","aria-label":"Permalink to “A checkpoint is an application contract”"},"​")],-1)),e[3]||(e[3]=t("p",null,"A versioned record binds authenticated tenant/subject/job, revision, allowed stage, artifact IDs/digests/schema, source/configuration versions, remaining call/byte/spend reservations, trusted UTC expiry and next permitted operation. References resolve only through an owned authorized store with a retention policy. A model-provided path, principal, “approved” flag or free-form function name is not a checkpoint.",-1)),e[4]||(e[4]=t("p",null,"Persist checked artifact plus advancing checkpoint in one transaction where possible. With separate object storage, stage the immutable bounded artifact, then commit a reference under compare-and-set; collect unreferenced staging objects later. Check digest/schema/owner on resume. A missing artifact is a recoverable failure or a documented safe-read restart, not an invitation to invent it.",-1)),c(n,{"encoded-source":"flowchart%20TD%0A%20%20%20%20Read%5BRead%20pending%5D%20--%3E%20Proposal%5BPersist%20checked%20proposal%20and%20operation%20ID%5D%0A%20%20%20%20Proposal%20--%3E%20Waiting%5BAwait%20trusted%20human%20decision%5D%0A%20%20%20%20Waiting%20--%3E%7Creject%20expire%20revoke%7C%20Stop%5BStopped%5D%0A%20%20%20%20Waiting%20--%3E%7Cexact%20approval%7C%20Execute%5BReauthorize%20and%20execute%5D%0A%20%20%20%20Execute%20--%3E%7Creceipt%20known%7C%20Done%5BPersist%20completed%20result%5D%0A%20%20%20%20Execute%20--%3E%7Creply%20lost%7C%20Unknown%5BOutcome%20uncertain%5D%0A%20%20%20%20Unknown%20--%3E%20Reconcile%5BQuery%20original%20operation%20under%20current%20authority%5D%0A%20%20%20%20Reconcile%20--%3E%7Ccommitted%7C%20Done%0A%20%20%20%20Reconcile%20--%3E%7Csafe%20to%20retry%20same%20key%7C%20Execute%0A%20%20%20%20Reconcile%20--%3E%7Cunavailable%7C%20Unknown"}),e[5]||(e[5]=d('<h2 id="recover-according-to-the-boundary" tabindex="-1">Recover according to the boundary <a class="header-anchor" href="#recover-according-to-the-boundary" aria-label="Permalink to “Recover according to the boundary”">​</a></h2><table tabindex="0"><thead><tr><th>Interruption</th><th>Durable evidence / permitted continuation</th></tr></thead><tbody><tr><td>Before a read dispatch</td><td>Reserved attempt/checkpoint; retry only within remaining deadline/caps</td></tr><tr><td>After a read, before checkpoint</td><td>Read can repeat under current scope and another charged attempt; orphan artifact cleanup required</td></tr><tr><td>Awaiting approval</td><td>Reload exact command and authenticated decision; model/tool text grants nothing</td></tr><tr><td>After approval, before local mutation</td><td>Recheck owner/version/expiry/digest and use the same operation ID</td></tr><tr><td>After local commit, before reply/checkpoint</td><td>Replay the exact approved operation to obtain its existing receipt; do not create a new key</td></tr><tr><td>Remote write timed out</td><td>Persist unknown; reconcile the remote authority&#39;s status/idempotency contract before retry</td></tr><tr><td>Current access revoked/configuration stale/artifact missing</td><td>Stop or take an explicitly reviewed safe transition; never publish cached private text</td></tr></tbody></table><p>The SQLite rename executor commits title/version and receipt atomically in one database. Its receipt replay is narrower than exactly-once delivery. A transaction on the job row cannot roll back an email or payment. For an external system use its supported operation key/status semantics and, where needed, a transactional outbox; an outbox consumer must still be idempotent.</p><h2 id="retries-cancellation-and-clocks" tabindex="-1">Retries, cancellation and clocks <a class="header-anchor" href="#retries-cancellation-and-clocks" aria-label="Permalink to “Retries, cancellation and clocks”">​</a></h2><p>A retry policy classifies temporary read failures, applies backoff/jitter and respects server minima within the overall budget. Credential/schema/permission failures and ambiguous effect outcomes do not receive the same automatic policy. Disable stacked SDK retries when the application owns attempts. Cancellation propagates and releases local tasks/clients; do not catch it as a transient error and restart work.</p><p>Use monotonic time within one process. Persist UTC expiry with a declared clock/skew policy across restarts, then derive a conservative remaining local duration. Check expiry before dispatch and wrap actual awaited work in an enforced cooperative timeout. A preflight timestamp alone cannot stop a blocking parser or a noncooperative adapter; those need a separate worker/process owner.</p><p>Once a mutation commits, request cancellation cannot undo it. A requested undo is a new authorized versioned operation. Cancellation before dispatch may revoke pending approval; after dispatch preserve uncertainty until the authoritative outcome is known.</p><h2 id="concurrent-owners-and-resource-accounting" tabindex="-1">Concurrent owners and resource accounting <a class="header-anchor" href="#concurrent-owners-and-resource-accounting" aria-label="Permalink to “Concurrent owners and resource accounting”">​</a></h2><p>Reserve an attempt <strong>atomically before dispatch</strong>, not after reading a shared counter. Persist a stable operation intent so another owner does not interpret a stale checkpoint as new work. Compare-and-set protects row updates; it does not prevent two workers from both making an external call before saving. Production concurrent runners need a claim/lease with fencing and reconciliation for expired claims. Lease expiry alone proves neither that work stopped nor that money is refundable.</p><p>Reserve a conservative whole-job spend maximum in the shared ledger. Pending means reconcile, settled means reuse a result, and unknown usage stays held under policy. Account counts/bytes and monetary reservation are distinct. Real provider charges can exceed a bad estimate; alert/stop new work rather than silently report the estimate as an enforced remote cap.</p><h2 id="what-the-workbench-establishes" tabindex="-1">What the workbench establishes <a class="header-anchor" href="#what-the-workbench-establishes" aria-label="Permalink to “What the workbench establishes”">​</a></h2><p>The <a href="./../../workbench/applied-ai/python/">runnable collection</a> has real-file state/CAS, approval/receipt/reopen/rollback, shared reservation and projected trace tests. These components do not implement the full artifact transaction, authenticated approval UI, distributed claim/lease or remote-effect reconciliation service above. The explanation makes those integration obligations concrete; <a href="./../../practice/applied-ai/resumable-workflow.html">P-335 checkpoints</a> specify independent implementation and evidence.</p><p>Evaluate complete tasks under normal, denial, interruption, revocation, budget and unknown-outcome schedules. Safe traces correlate stage/revision/attempt/duration and fixed outcomes; durable receipts/audit provide separate authority. No amount of fluent model explanation can replace those observations.</p>',13))])}const v=r(l,[["render",p]]);export{g as __pageData,v as default};
